/**
 * Drills into a funnel insight to list the persons behind one step — either those who converted through it or those who dropped off at it. Returned rows are `distinct_id`, `email`, `name`, and optionally matched session recordings.
 *
 * Pair this with `query-funnel`: run the funnel query first to read the per-step counts, then call this tool with the **same** funnel query as `source`. There are two mutually exclusive modes, and the mode must match the source funnel's `funnelsFilter.funnelVizType`:
 *
 * 1. **Step mode** (source `funnelVizType: "steps"`, the default): use `funnelStep` to pick a step.    A **positive** value lists actors who converted **through** that step; a **negative** value lists    actors who **dropped off** at it. Steps are 1-based, so `funnelStep: 2` = converted through step 2,    `funnelStep: -2` = dropped off at step 2. (You cannot drop off at step 1, so the smallest negative    value is `-2`.) Add `funnelStepBreakdown` to scope to one breakdown series.
 *
 * 2. **Trends-dropoff mode** (source `funnelVizType: "trends"`): use `funnelTrendsDropOff` together with    `funnelTrendsEntrancePeriodStart` to list the persons behind one point of a funnel-trends    (conversion-over-time) chart.
 *
 * The funnel's `time_to_convert` viz type has no persons drilldown — do not use this tool with it.
 */
export interface QueriesQueryFunnelActorsDataQuerySource {
    /** Step mode only (source `funnelVizType: "steps"`). The 1-based index of the step to drill into.
     * **Positive** lists actors who converted through that step; **negative** lists actors who dropped off at it. E.g. `2` = converted through step 2, `-2` = dropped off at step 2. The smallest negative value is `-2` (no one can drop off at the entry step). */
    funnelStep?: QueriesQueryFunnelActorsResponseInteger
    /** Step mode only. Scope the actors to a single breakdown series. Pass the breakdown value(s) from the matching `query-funnel` result row verbatim (an array, e.g. `["Chrome"]`). Omit for the baseline (non-breakdown) series. */
    funnelStepBreakdown?: string[]
    /** Trends-dropoff mode only (source `funnelVizType: "trends"`). When `true`, list the actors who dropped off; when `false`, list those who converted. Use together with `funnelTrendsEntrancePeriodStart`. */
    funnelTrendsDropOff?: boolean
    /** Trends-dropoff mode only. The entrance period to drill into, as a `YYYY-MM-DD HH:mm:ss` string (e.g. `'2024-01-15 00:00:00'`), taken from the funnel-trends point the user is asking about. Use together with `funnelTrendsDropOff`. */
    funnelTrendsEntrancePeriodStart?: string
    /** Whether to include matched session recordings for each actor. */
    includeRecordings?: boolean
    kind: 'FunnelsActorsQuery'
    /** Maximum number of persons to return in one page, from 1 to 1000. Higher values are clamped. */
    limit?: QueriesQueryFunnelActorsResponseInteger
    /** Number of persons to skip before the returned page. Use it with `limit` to walk the whole result set: the response reports `limit`, `offset`, and `hasMore`, so when `hasMore` is true, call again with `offset` raised by `limit`. */
    offset?: QueriesQueryFunnelActorsResponseInteger
    /** The source funnel insight query whose step (or trends point) we are drilling into. */
    source: QueriesQueryFunnelActorsResponseAssistantFunnelsQuery
}

